// NODE 2 - CLEAN AND NORMALISE DATA
// CONFIGURE: Adjust field label strings on lines 12-16
// if your Tally form uses different field labels.

const body = $input.first().json.body || $input.first().json;
const fields = body.fields || [];

const getField = (label) => {
  const f = fields.find(f =>
    f.label && f.label.toLowerCase().includes(label.toLowerCase())
  );
  return f ? (f.value || '').toString().trim() : '';
};

const name    = getField('name') || getField('full name') || '';
const email   = (getField('email') || '').toLowerCase().trim();
const phone   = getField('phone') || getField('telephone') || '';
const message = getField('message') || getField('enquiry') || '';
const source  = body.formName || 'tally-form';

if (!name || !email || !message) {
  return [{ json: { status: 'Invalid', error: 'Missing required fields' } }];
}

const suffix  = Math.random().toString(36).substring(2, 6);
const lead_id = Date.now() + '-' + suffix;

let normPhone = phone.replace(/[\s\-\(\)]/g, '');
if (normPhone.startsWith('0') && normPhone.length === 11) {
  normPhone = '+44' + normPhone.slice(1);
}

return [{ json: {
  lead_id,
  timestamp: new Date().toISOString(),
  name, email,
  phone: normPhone || phone,
  message, source
}}];

