// NODE 5 - PARSE GROQ RESPONSE
// CONFIGURE: No changes needed.
// Handles markdown fences and JSON parse failures gracefully.

const fallback = 'Thank you for your enquiry. We have received your message and a member of our team will be in touch with you shortly.';

try {
  const data = $input.first().json;
  let raw = data.choices[0].message.content;

  raw = raw.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();

  const p = JSON.parse(raw);

  return [{ json: {
    ...$input.first().json,
    reply:          p.reply          || fallback,
    classification: (p.classification || 'warm').toLowerCase(),
    urgency:        (p.urgency        || 'medium').toLowerCase(),
    intent:         p.intent          || 'researching',
    reason:         p.reason          || '',
    priority:       p.priority        || 'Medium',
    parse_success:  true
  }}];

} catch (err) {
  return [{ json: {
    ...$input.first().json,
    reply:         fallback,
    classification:'warm',
    urgency:       'medium',
    intent:        'researching',
    reason:        'Parse error - fallback used',
    priority:      'Medium',
    parse_success: false,
    parse_error:   err.message
  }}];
}

